# ============================================================
# GROUP 01 — Anatomy & Physiology of the Kidney
# ============================================================
anatomy = [
 {"cat":"Functions","q":"List the five major functions of the kidneys.",
  "a": "<ul><li>1. Regulation of body fluid osmolarity and volume</li><li>2. Regulation of electrolyte balance</li><li>3. Regulation of acid-base balance</li><li>4. Excretion of metabolic products and foreign substances</li><li>5. Production and secretion of hormones</li></ul>Regulatory + excretory + endocrine roles."},
 {"cat":"Gross Anatomy","q":"Describe the gross structure of the kidney.",
  "a": "Outer <b>cortex</b> and inner <b>medulla</b>, both composed of nephrons (functional units). The <b>pelvis</b> is the upper expanded region of the ureter; it divides into 2–3 <b>major calyces</b> → <b>minor calyces</b>. The medial indentation (hilum) transmits the renal artery, vein, nerves and pelvis."},
 {"cat":"Ultrastructure","q":"What is ultrafiltration and what structures form the filtration barrier?",
  "a": "Ultrafiltration = passive movement of an essentially <b>protein-free fluid</b> from glomerular capillaries into Bowman's space. <b>Filtration barrier:</b> fenestrated capillary endothelium → basement membrane → podocyte foot processes (with slit diaphragms bridging the filtration slits)."},
 {"cat":"Ultrastructure","q":"Trace the route from Bowman's capsule to the tubule.",
  "a": "Podocytes form the visceral layer of Bowman's capsule; the visceral cells reflect at the <b>vascular pole</b> to form the parietal layer; the space between = Bowman's space, which at the <b>urinary pole</b> becomes the lumen of the proximal tubule."},
 {"cat":"Filtration","q":"What does the glomerular ultrafiltrate contain — and what is excluded?",
  "a": "Contains everything in plasma: electrolytes, glucose, phosphate, urea, creatinine, peptides, low-MW proteins. <b>Excluded: proteins with MW &gt;68,000</b> (albumin, globulin) — the filtrate is essentially protein-free."},
 {"cat":"Filtration","q":"Which organ is the major excretory organ during fetal life?",
  "a": "The <b>placenta</b>."},
]

