# GROUP 03 — Hematuria
# ============================================================
hematuria = [
 {"cat":"Definition","q":"Define microscopic and macroscopic hematuria.",
  "a": "<b>Microscopic:</b> more than <b>5 RBCs per high-power field</b> in the sediment of 10 ml of centrifuged freshly voided urine. <b>Macroscopic:</b> grossly visible blood — pink or red; cola/smoky when of glomerular origin."},
 {"cat":"Causes","q":"Classify the causes of hematuria in children.",
  "a": "<b>Glomerular</b> — isolated renal disease (IgA nephropathy, PSGN, membranous, MPGN, FSGS, anti-GBM) or multi-system disease (SLE, HSP, Goodpasture, HUS, sickle cell, HIV). <b>Extra-glomerular</b> — upper tract (tubulointerstitial: pyelonephritis/AIN/ATN; vascular: thrombosis/malformations; crystalluria; anatomical: cystic disease, Wilms, trauma) or lower tract (cystitis, urethritis, urolithiasis)."},
 {"cat":"Causes","q":"List common causes of GROSS hematuria in children.",
  "a": "<b>Extra-glomerular:</b> UTI, meatal stenosis, perineal irritation, trauma, urolithiasis/hypercalciuria, coagulopathy, tumor. <b>Glomerular:</b> IgA nephropathy (Berger), Alport syndrome, thin GBM nephropathy, PSGN, HSP nephritis, SLE nephritis. <b>Recurrent gross hematuria → think IgA nephropathy.</b>"},
 {"cat":"Evaluation","q":"Differentiate renal (glomerular/upper tract) from urinary tract (lower tract) hematuria.",
  "a": "<ul><li>Colour: <b>cola/smoky</b> (renal) vs <b>pink/red</b> (lower tract)</li><li>RBCs: <b>dysmorphic</b> (renal) vs normal</li><li><b>RBC casts present</b> in renal; <b>blood clots</b> in lower tract</li><li>Proteinuria &gt;100 mg/dL in renal; minimal in lower tract</li><li>Clinical: edema/hypertension (renal) vs dysuria (lower tract)</li></ul>"},
 {"cat":"Evaluation","q":"How do you localize hematuria by laboratory approach?",
  "a": "<b>Glomerular:</b> reduced C3 → PSGN, lupus nephritis, nephritis with chronic infection, MPGN; ASO titre/anti-DNase/throat or skin culture for PSGN; ANA + anti-dsDNA for lupus. <b>Extra-glomerular:</b> urine culture (UTI); 24-h urine calcium/uric acid/oxalate (crystalluria, stones); cystogram &amp; renal scan (hydronephrosis); renal Doppler (renal vein thrombosis)."},
 {"cat":"Evaluation","q":"List the indications for renal biopsy in hematuria.",
  "a": "<ol><li>Unexplained persistent or recurrent gross hematuria</li><li>Lupus nephritis</li><li>Glomerulonephritis with nephritic-nephrotic picture or absent low C3</li><li>Unexplained acute renal failure</li></ol>"},
]

