# GROUP 04 — Acute Post-Streptococcal GN
# ============================================================
apsgn = [
 {"cat":"Definition","q":"Define APSGN and its 4 cardinal features.",
  "a": "Acute, specific, self-limited glomerulonephritis due to prior streptococcal infection with: 1. sudden onset <b>gross hematuria</b>, 2. mild-to-moderate <b>edema</b>, 3. <b>hypertension</b>, 4. <b>oliguria</b> (may be present)."},
 {"cat":"Etiology","q":"Compare throat vs skin streptococcal infection in APSGN.",
  "a": "<ul><li><b>Throat:</b> strains 4 &amp; 12; winter/spring; latent period <b>1–2 weeks</b>; ASO titre elevated</li><li><b>Skin:</b> strain <b>49</b>; summer; latent period <b>2–3 weeks</b>; ASO may be normal</li></ul>"},
 {"cat":"Pathology","q":"Describe the pathology of APSGN (gross, LM, IF, EM).",
  "a": "Gross: symmetrically enlarged kidneys. LM: all glomeruli enlarged and bloodless, diffuse mesangial cell proliferation with increased matrix. IF: <b>lumpy-bumpy</b> deposits of immunoglobulin + complement on the GBM and mesangium. EM: electron-dense deposits (<b>humps</b>) on the <b>epithelial side</b> of the GBM."},
 {"cat":"Clinical","q":"What is the typical age and presentation of APSGN?",
  "a": "Age <b>5–12 years</b> (uncommon before 3 years). Acute nephritic syndrome 1–2 wk after pharyngitis or 3–6 wk after pyoderma: edema (salt &amp; water retention), hypertension, oliguria; spectrum from asymptomatic microscopic hematuria to AKI; possible encephalopathy/heart failure; non-specific malaise, lethargy, fever, abdominal/flank pain."},
 {"cat":"Clinical","q":"What are the natural course and complications of APSGN?",
  "a": "Acute phase resolves within <b>6–8 weeks</b>; proteinuria/HTN normalize by ~6 wk; microscopic hematuria may persist 1–2 years. Complications: <b>hypertension in 60%</b> (hypertensive encephalopathy in 10%), heart failure, hyperkalemia, hyperphosphatemia, hypocalcemia, acidosis, seizures, uremia. <b>Emergencies: hyperkalemia, hypertensive encephalopathy, CHF, RPGN.</b>"},
 {"cat":"Diagnosis","q":"How is APSGN diagnosed?",
  "a": "Urine: smoky/cola color, oliguria, high specific gravity, <b>dysmorphic RBCs + RBC casts</b>, nephritic-range proteinuria, leukocytes. <b>Serum C3 reduced in the acute phase, returns to normal 6–8 wk</b>. Evidence of streptococcal infection: rising ASOT (pharyngeal) or <b>anti-DNase B (best for cutaneous infection)</b>; throat culture may just show carrier state."},
 {"cat":"Diagnosis","q":"When is renal biopsy considered in APSGN?",
  "a": "AKI with RPGN; nephrotic-range proteinuria; <b>absence of evidence of streptococcal infection</b>; normal complement; or persistence of hematuria/proteinuria/low C3 for &gt;2 months after onset."},
 {"cat":"Treatment","q":"Outline treatment of APSGN.",
  "a": "<b>General:</b> bed rest only during the oliguric phase; fluid intake = <b>UOP + 400 ml/m²</b>; protein &amp; salt restriction; high-carbohydrate diet. <b>Specific:</b> manage renal insufficiency &amp; hypertension; <b>10-day course of penicillin</b> to eradicate streptococci (does not alter the natural history). Prevention: early antibiotics do NOT eliminate GN risk; culture &amp; treat family contacts."},
 {"cat":"Prognosis","q":"What is the prognosis of APSGN?",
  "a": "Complete recovery in <b>&gt;95%</b>; mortality in the acute stage avoidable with good management; rarely severe acute phase → glomerular hyalinization and chronic renal insufficiency; <b>recurrences are extremely rare</b>."},
]

