proteinuria = [
 {"cat":"Detection","q":"How is proteinuria detected and quantified?",
  "a": "<ul><li><b>Dipstick:</b> qualitative, detects mainly albuminuria</li><li><b>24-h urine:</b> normal ≤<b>150 mg/24 h (4 mg/m²/hr)</b>; nephritic range 4–40 mg/m²/hr; <b>nephrotic &gt;40 mg/m²/hr</b></li><li><b>Upr/UCr ratio:</b> normal &lt;0.2 (≥2 y) or &lt;0.5 (&lt;2 y); nephritic 0.2–2; <b>nephrotic &gt;2</b></li></ul>"},
 {"cat":"Classification","q":"List causes of transient proteinuria.",
  "a": "Fever, exercise, dehydration, cold exposure, seizure."},
 {"cat":"Classification","q":"Describe orthostatic (postural) proteinuria.",
  "a": "The <b>most common cause of persistent proteinuria</b> in school-aged children/adolescents (up to <b>60%</b>). Normal or slightly increased protein supine; increases up to <b>10-fold upright (up to 1 g/24 hr)</b>. No hematuria, hypertension, or renal dysfunction; benign; follow-up prudent if protein &gt;1,000 mg/24 h."},
 {"cat":"Classification","q":"What is glomerular vs tubular proteinuria?",
  "a": "<b>Glomerular:</b> increased GBM permeability — 1 to &gt;3 g/24 h; selective (albumin up to its MW) or non-selective (albumin + IgG); associated with HTN, hematuria, renal dysfunction. <b>Tubular:</b> proximal tubular injury → diminished reabsorption — fixed low-grade (&lt;1 g/24 h), low-MW proteins, with glucosuria, phosphaturia, bicarbonate wasting, aminoaciduria. Distinguish by <b>urine electrophoresis</b> (albumin major in glomerular; little/no albumin in tubular)."},
 {"cat":"Evaluation","q":"What is the initial evaluation of persistent fixed proteinuria?",
  "a": "Serum creatinine, 24-h urinary protein excretion, serum albumin, and C3. Low-grade proteinuria (150–1,000 mg/24 h) with normal findings may not need biopsy — periodic re-evaluation (physical exam, BP, urinalysis, creatinine, 24-h protein)."},
]

