# GROUP 06 — Nephrotic Syndrome
# ============================================================
ped_ns = [
 {"cat":"Definition","q":"Define nephrotic syndrome (the tetrad) and its epidemiology.",
  "a": "Tetrad: 1. <b>Heavy proteinuria</b> (&gt;3.5 g/24 h adults; <b>&gt;40 mg/m²/hr children</b>), 2. <b>Hypoalbuminemia &lt;2.5 g/dL</b>, 3. Generalized edema, 4. Hyperlipidemia (cholesterol &gt;250 mg/dL). Pediatrics: <b>15× more common than in adults</b>; incidence 2–3/100,000 children/year; mostly steroid-sensitive MCD."},
 {"cat":"Etiology","q":"Classify the etiology of nephrotic syndrome.",
  "a": "<b>Idiopathic (~90%)</b> — three histological types: <b>Minimal Change Disease, Diffuse Mesangial Proliferation, FSGS</b> (may be separate diseases or a spectrum). <b>Secondary:</b> SLE, HSP. <b>Congenital:</b> see early-onset NS (1st year)."},
 {"cat":"Pathogenesis","q":"Explain the pathogenesis of the nephrotic tetrad.",
  "a": "<b>Proteinuria:</b> ↑ GBM permeability (size/charge defect); selective (albumin, transferrin, IgG) vs non-selective. <b>Hypoproteinemia</b> (mainly hypoalbuminemia). <b>Edema:</b> ↓ plasma oncotic pressure → fluid to interstitial tissue (lax, gravity-dependent). <b>Hyperlipidemia:</b> liver ↑ synthesis of lipoproteins (not lost in urine) + ↓ lipoprotein lipase → ↓ lipid catabolism."},
 {"cat":"Pathogenesis","q":"How is edema amplified in NS (aldosterone/ADH)?",
  "a": "↓ intravascular volume → ↓ renal blood flow → <b>JGA → ↑ aldosterone → Na⁺ &amp; water retention</b> → more edema; also ↓ intravascular volume → <b>↑ ADH → water retention</b>."},
 {"cat":"Pathology","q":"Describe the pathology of minimal change disease (MCNS).",
  "a": "<b>85% of cases.</b> LM: normal or minimal mesangial increase. IF: typically negative. <b>EM: effacement of epithelial cell foot processes.</b> &gt;95% respond to corticosteroids."},
 {"cat":"Clinical","q":"What is the clinical picture of childhood NS?",
  "a": "M:F = <b>2:1</b>; peak age <b>2–6 years</b>; often after minor infections/insect bites. Mild edema around <b>eyes and lower extremities</b> → generalized with ascites, pleural effusions, genital edema. Anorexia, irritability, abdominal pain, diarrhea. <b>Hypertension and gross hematuria are uncommon.</b>"},
 {"cat":"Diagnosis","q":"What are the diagnostic criteria of NS on urine and blood?",
  "a": "Urine: yellowish <b>frothy</b>, high specific gravity, protein 3+/4+ (&gt;40 mg/m²/hr; Upr/UCr &gt;2.0); microscopic hematuria in ~20%; waxy (lipoid) &amp; hyaline casts. Blood: albumin &lt;2.5 g/dL, total protein &lt;4.5 g/dL, ↑ cholesterol/triglycerides, <b>C3/C4 normal</b>, creatinine usually normal."},
 {"cat":"Diagnosis","q":"When is renal biopsy indicated in pediatric NS?",
  "a": "<b>Before treatment:</b> hematuria, hypertension, renal insufficiency, hypocomplementemia, age &lt;1 y or &gt;10 y, low C3. <b>After treatment:</b> frequent relapsers, steroid-resistant. Biopsy is NOT required for diagnosis in most children."},
 {"cat":"Treatment","q":"Outline supportive treatment of NS.",
  "a": "Monitor (24-h protein, daily weight, infection signs, BP, urine output); low-sodium diet (normalize in remission); fluid restriction if hyponatremia/progressive weight loss; hospitalize severe symptomatic edema (large effusions, anasarca, genital edema); <b>judicious diuretics</b> (risk of thromboembolism/hypovolemia); salt-free albumin IV 25% (0.5 g/kg/12 h) + furosemide 1–2 mg/kg for anasarca with respiratory difficulty; albumin alone for hypovolemic shock."},
 {"cat":"Treatment","q":"Describe steroid therapy for the first episode of NS.",
  "a": "<b>Prednisone 60 mg/m²/day (max 60 mg/day)</b> in 2–3 divided doses for at least 4 weeks → then <b>40 mg/m² every other day</b> as a single morning dose, tapered over 2–3 months. Response = urine trace/negative for protein for 3 consecutive days (80–90% respond)."},
 {"cat":"Treatment","q":"Define the response categories in NS.",
  "a": "<b>No relapse:</b> remission without relapse. <b>Steroid-dependent:</b> relapse on alternate-day therapy or within 14 days of stopping. <b>Frequent relapsers:</b> ≥4 relapses in 12 months. <b>Steroid-resistant:</b> failure to respond within 4–6 weeks → diagnostic renal biopsy."},
 {"cat":"Treatment","q":"How is relapse treated, and what are the alternative agents?",
  "a": "Daily divided-dose prednisone until remission, then alternate-day taper over 1–2 months. Alternatives (steroid-dependent/frequent relapsers/resistant or severe steroid toxicity): <b>cyclophosphamide, methylprednisolone, cyclosporine</b>, ACE inhibitors/ARBs as adjuvant to reduce proteinuria; low-dose aspirin (↓ thrombosis); levamisole (consolidates remission); pneumococcal &amp; H. influenza vaccines."},
 {"cat":"Complications","q":"Why is infection the major complication of NS, and what is the pattern?",
  "a": "Urinary losses of immunoglobulins &amp; properdin B; defective cell-mediated immunity; immunosuppressives; malnutrition; edema fluid as culture medium; abnormal leukocyte function; splenic hypoperfusion. <b>Spontaneous bacterial peritonitis is the most frequent type</b> (S. pneumoniae most common; E. coli also); sepsis, pneumonia, cellulitis, UTI."},
 {"cat":"Complications","q":"What is the risk and prevention of thromboembolism in pediatric NS?",
  "a": "Incidence <b>2–5%</b> (lower than adults): renal vein thrombosis, pulmonary embolus, sagittal sinus thrombosis, catheter thromboses. Mechanisms: ↑ prothrombotic factors (fibrinogen, thrombocytosis, hemoconcentration) and ↓ fibrinolytic factors (urinary loss of antithrombin III, proteins C &amp; S) + hyperlipidemia. <b>Prophylactic anticoagulation NOT recommended</b> unless previous thromboembolic event; avoid aggressive diuresis; limit indwelling catheters."},
 {"cat":"Prognosis","q":"What should you tell the family about steroid-responsive NS?",
  "a": "Relapses generally <b>decrease with age</b>; the child will <b>not develop chronic renal failure</b>; the disease is generally not hereditary; fertility is preserved (without prolonged cyclophosphamide); when in remission the child is normal with unrestricted diet/activity."},
 {"cat":"Early-onset","q":"List the causes of early-onset NS in the first year of life.",
  "a": "<b>1. Congenital NS — Finnish type:</b> AR, defect in <b>nephrin</b> in the GBM; presents in first 3 months; large edematous placenta at birth; poor prognosis → CRF; treat with albumin, ACE inhibitors, NSAIDs, nephrectomy + transplantation. 2. Congenital infections (TORCH). 3. Denys-Drash syndrome (Wilms tumor + GU anomalies + NS). 4–5. Drug-induced / idiopathic."},
]

