# GROUP 07 — Acute Kidney Injury (Pediatric)
# ============================================================
ped_aki = [
 {"cat":"Definition","q":"Define pediatric AKI and its epidemiology.",
  "a": "Rapid decline (hours to days) in GFR causing impaired nitrogenous waste excretion and loss of water/electrolyte/acid-base regulation. Occurs in <b>2–3% of pediatric admissions</b> and up to <b>8% of NICU infants</b>."},
 {"cat":"Grading","q":"Summarize the modified pediatric RIFLE (pRIFLE) criteria.",
  "a": "<b>Risk:</b> GFR ↓ by 25%. <b>Injury:</b> GFR ↓ by 50%. <b>Failure:</b> GFR ↓ by 75% (or &lt;35 ml/min/1.73 m²). <b>Loss:</b> persistent failure &gt;4 weeks. <b>End-stage:</b> &gt;3 months."},
 {"cat":"Pathogenesis","q":"List the three categories of pediatric AKI.",
  "a": "<ul><li><b>Prerenal:</b> diminished effective circulating arterial volume → ↓ renal perfusion → ↓GFR; <b>no kidney damage</b>; reversible if promptly corrected</li><li><b>Intrinsic renal:</b> renal parenchymal damage (ischemia, GN, ATN, interstitial nephritis)</li><li><b>Post-renal:</b> urinary tract obstruction (must be bilateral with two functioning kidneys); relief usually → recovery</li></ul>"},
 {"cat":"Causes","q":"List common causes of prerenal, intrinsic and postrenal AKI in children.",
  "a": "<b>Prerenal:</b> dehydration, hemorrhage, sepsis, hypoalbuminemia, cardiac failure. <b>Intrinsic:</b> glomerulonephritis (post-infectious, lupus, HSP, MPGN, anti-GBM, HUS), ATN (cortical necrosis, renal vein thrombosis), acute interstitial nephritis (tumor infiltration, tumor lysis). <b>Postrenal:</b> posterior urethral valve, PUJ/UVJ obstruction, ureterocele, tumors, urolithiasis, hemorrhagic cystitis, neurogenic bladder."},
 {"cat":"Clinical","q":"Describe the oliguric and polyuric phases of AKI.",
  "a": "<b>Oliguric phase (early):</b> oliguria/anuria, edema, hypertension, acidotic breathing, metabolic acidosis. <b>Advanced:</b> uremic encephalopathy (confusion–convulsion–coma), ↓Na → convulsions, ↑K → arrhythmias, hypervolemia → heart failure/pulmonary edema, GIT stress ulcer. <b>Polyuric phase:</b> indicates early recovery — new tubular cells can't retain fluid/electrolytes → polyuria &amp; electrolyte loss."},
 {"cat":"Diagnosis","q":"How is AKI diagnosed and how do you distinguish prerenal from intrinsic?",
  "a": "Diagnosis: oliguria (UOP &lt;1 ml/kg/hr or &lt;400 ml/m²/day; anuria &lt;30 ml/m²/day), ↑ creatinine/urea, metabolic acidosis, hyperkalemia, dilutional hyponatremia, hypocalcemia, hyperphosphatemia. <b>Prerenal:</b> urine specific gravity &gt;1020, Uosm &gt;500 mOsm/kg, UNa &lt;20 mEq/L, FENa &lt;1%. <b>Intrinsic:</b> SG &lt;1010, Uosm &lt;350, UNa &gt;40, <b>FENa &gt;2%</b> (&gt;10% in neonates)."},
 {"cat":"Diagnosis","q":"What do muddy brown casts, WBC casts and RBC casts indicate in pediatric AKI?",
  "a": "Muddy brown casts → <b>ATN</b>; WBC casts (+eosinophils) → <b>AIN</b>; RBC casts → <b>acute glomerulonephritis</b>."},
 {"cat":"Treatment","q":"Outline treatment of pediatric AKI.",
  "a": "All children hospitalized for monitoring. <b>Treat the cause:</b> restore circulating volume (prerenal), treat underlying disease (antibiotics for infection, steroids/immunosuppression for GN), relieve obstruction (postrenal). <b>Correct electrolytes/acid-base:</b> hyperkalemia, hyponatremia, acidosis, hyperphosphatemia/hypocalcemia; adjust fluids and drug doses as renal function changes."},
]

